import {
  mutation,
  query,
  object,
  string,
  number,
  type MutationContext,
  type QueryContext,
} from "apps";
import { always } from "apps/operations/approval";
type Read = QueryContext<{ drive: true }>;
type Write = MutationContext<{ drive: true }>;
const uploadInput = object({ upload: string(), cursor: number().optional() });
const continuation = (input: { upload: string; cursor?: number | undefined }) => ({
  upload: input.upload,
  ...(input.cursor === undefined ? {} : { cursor: input.cursor }),
});
export const attachmentTools = {
  fileInfo: query(
    {
      description: "Read a file's size and retained attachment identity at one pinned revision.",
      input: object({ path: string(), at: string().optional() }),
    },
    (ctx: Read, input) =>
      ctx.drive.info({ path: input.path, ...(input.at === undefined ? {} : { at: input.at }) }),
  ),
  beginAttachment: mutation(
    {
      description:
        "Reserve and resume an immutable attachment upload. Send only the missing one MiB parts. Follow next with cursor to list further missing parts.",
      approval: always(),
      input: object({
        operation: string(),
        oid: string(),
        bytes: number(),
        cursor: number().optional(),
      }),
    },
    (ctx: Write, input) =>
      ctx.drive.beginAttachment({
        operation: input.operation,
        oid: input.oid,
        bytes: input.bytes,
        ...(input.cursor === undefined ? {} : { cursor: input.cursor }),
      }),
  ),
  uploadAttachmentPart: mutation(
    {
      description:
        "Store one exact attachment part. Repeating it after a lost reply never uploads different bytes.",
      approval: always(),
      input: object({ upload: string(), part: number(), contentBase64: string() }),
    },
    (ctx: Write, input) => ctx.drive.uploadAttachmentPart(input),
  ),
  completeAttachment: mutation(
    {
      description:
        "Verify up to sixteen MiB of an upload. Follow next with cursor until present. Only a complete SHA-256 match can be attached to a path.",
      approval: always(),
      input: uploadInput,
    },
    (ctx: Write, input) => ctx.drive.completeAttachment(continuation(input)),
  ),
  cancelAttachment: mutation(
    {
      description:
        "Cancel an unaccepted upload and reclaim a bounded page of parts. Follow next until null. Accepted bytes are never deleted.",
      approval: always(),
      input: uploadInput,
    },
    (ctx: Write, input) => ctx.drive.cancelAttachment(continuation(input)),
  ),
  attachFile: mutation(
    {
      description:
        "Save a verified attachment at a vault path against an exact Git base. Concurrent edits keep both versions for review.",
      approval: always(),
      input: object({
        base: string(),
        path: string(),
        operation: string(),
        oid: string(),
        bytes: number(),
      }),
    },
    (ctx: Write, input) => ctx.drive.attach(input),
  ),
};

import { query, object, array, string, number, jsonSchema, type QueryContext } from "apps";
type Read = QueryContext<{ drive: true }>;
export const changeTools = {
  changes: query(
    {
      description:
        "Read only file changes between pinned cloud versions. Start from null for first download, then follow next until null.",
      input: object({
        from: jsonSchema({ type: ["string", "null"] }),
        to: string(),
        cursor: object({
          from: jsonSchema({ type: ["string", "null"] }),
          to: string(),
          frames: array(object({ name: string(), after: string() })),
        }).optional(),
        limit: number().optional(),
      }),
    },
    (ctx: Read, input) => {
      const from = input.from;
      if (from !== null && typeof from !== "string")
        throw new TypeError("Expected a revision or null");
      const cursor = input.cursor;
      let continuation;
      if (cursor) {
        const from = cursor.from;
        if (from !== null && typeof from !== "string")
          throw new TypeError("Expected a cursor revision or null");
        continuation = { ...cursor, from };
      }
      return ctx.drive.changes({
        from,
        to: input.to,
        ...(continuation ? { cursor: continuation } : {}),
        ...(input.limit === undefined ? {} : { limit: input.limit }),
      });
    },
  ),
};

import {
  mutation,
  query,
  object,
  array,
  string,
  number,
  boolean,
  jsonSchema,
  type MutationContext,
  type QueryContext,
} from "apps";
import { always } from "apps/operations/approval";
type Read = QueryContext<{ drive: true }>;
type Write = MutationContext<{ drive: true }>;
const identity = object({ id: string() });
export const importTools = {
  importStatus: query(
    {
      description:
        "Read the vault's counted initial import, including confirmed files, removed source files and its separate operation allowance.",
      input: object({ id: string().optional() }),
    },
    (ctx: Read, input) => ctx.drive.importStatus(input.id === undefined ? {} : { id: input.id }),
  ),
  planImport: mutation(
    {
      description:
        "Declare up to 100 initial source files per stable page before uploading. The final page reserves a counted one-time allowance. Later final pages may amend unclaimed files or record removed source paths; prior pages remain immutable.",
      approval: always(),
      input: object({
        id: string(),
        page: number(),
        entries: array(object({ path: string(), kind: string(), bytes: number(), hash: string() })),
        removed: array(string()).optional(),
        final: boolean(),
      }),
    },
    (ctx: Write, input) =>
      ctx.drive.planImport({
        ...input,
        entries: input.entries.map((entry) => {
          if (entry.kind !== "note" && entry.kind !== "attachment")
            throw new TypeError("Invalid initial import file kind");
          return { ...entry, kind: entry.kind };
        }),
        ...(input.removed === undefined ? {} : { removed: input.removed }),
      }),
  ),
  importRequest: mutation(
    {
      description:
        "Run a manifest-bound initial import request using its reserved allowance. Only import uploads and reconciliation reads are accepted. Every retry and storage operation is counted.",
      approval: always(),
      input: object({ id: string(), request: jsonSchema({ type: "object" }) }),
    },
    (ctx: Write, input) => {
      if (
        input.request === null ||
        typeof input.request !== "object" ||
        Array.isArray(input.request)
      )
        throw new TypeError("Invalid initial import request");
      return ctx.drive.runImport({
        id: input.id,
        request: Object.fromEntries(Object.entries(input.request)),
      });
    },
  ),
  finishImport: mutation(
    {
      description:
        "Close the one-time allowance after every declared file has a confirmed saved version or an explicit removed-source record. Unspent credit is released; counted usage and files are retained.",
      approval: always(),
      input: identity,
    },
    (ctx: Write, input) => ctx.drive.finishImport(input),
  ),
};

import { attachmentTools } from "./attachments.ts";
import { importTools } from "./imports.ts";
import { changeTools } from "./changes.ts";
import {
  array,
  defineApp,
  jsonSchema,
  mutation,
  number,
  object,
  query,
  router,
  string,
  type MutationContext,
  type QueryContext,
} from "apps";
import { always } from "apps/operations/approval";

export const requirements = { drive: true } as const;
type Read = QueryContext<typeof requirements>;
type Write = MutationContext<typeof requirements>;
const listCursor = object({ at: string(), path: string(), after: string() });
const searchCursor = object({
  at: string(),
  query: string(),
  frames: array(object({ path: string(), after: string() })),
  pending: object({ path: string(), offset: number(), line: number(), tail: string() }).optional(),
});
const file = object({
  path: string(),
  at: string().optional(),
  offset: number().optional(),
  maxBytes: number().optional(),
});
const readInput = (input: {
  path: string;
  at?: string | undefined;
  offset?: number | undefined;
  maxBytes?: number | undefined;
}) => ({
  path: input.path,
  ...(input.at === undefined ? {} : { at: input.at }),
  ...(input.offset === undefined ? {} : { offset: input.offset }),
  ...(input.maxBytes === undefined ? {} : { maxBytes: input.maxBytes }),
});
const write = object({ base: string(), path: string(), content: string(), operation: string() });
const applyNotes = mutation(
  {
    description:
      "Apply 1 to 100 text changes atomically against one exact cloud revision. Reuse the operation id after an unknown reply.",
    approval: always(),
    input: object({
      base: string(),
      operation: string(),
      edits: array(object({ path: string(), content: jsonSchema({ type: ["string", "null"] }) })),
    }),
  },
  (ctx: Write, input) =>
    ctx.drive.apply({
      ...input,
      edits: input.edits.map((edit) => {
        if (edit.content !== null && typeof edit.content !== "string")
          throw new TypeError("Batch content must be text or null");
        return { ...edit, content: edit.content };
      }),
    }),
);
const listNotes = query(
  {
    description:
      "List this vault's cloud notes and folders at one pinned version. Pass the returned next cursor to continue. Devices may be off.",
    input: object({
      path: string().optional(),
      at: string().optional(),
      cursor: listCursor.optional(),
      limit: number().optional(),
    }),
  },
  (ctx: Read, input) =>
    ctx.drive.list({
      ...(input.path === undefined ? {} : { path: input.path }),
      ...(input.at === undefined ? {} : { at: input.at }),
      ...(input.cursor === undefined ? {} : { cursor: input.cursor }),
      ...(input.limit === undefined ? {} : { limit: input.limit }),
    }),
);
const readNote = query(
  {
    description:
      "Read up to 256 KiB of a cloud note. Continue with offset=next and the same at; null next means complete.",
    input: file,
  },
  (ctx: Read, input) => ctx.drive.read(readInput(input)),
);
const searchNotes = query(
  {
    description:
      "Search the complete cloud vault. Follow cursor until complete is true; each page has a bounded scan budget.",
    input: object({
      query: string(),
      at: string().optional(),
      cursor: searchCursor.optional(),
      limit: number().optional(),
      maxFiles: number().optional(),
    }),
  },
  (ctx: Read, input) =>
    ctx.drive.search({
      query: input.query,
      ...(input.at === undefined ? {} : { at: input.at }),
      ...(input.cursor === undefined ? {} : { cursor: input.cursor }),
      ...(input.limit === undefined ? {} : { limit: input.limit }),
      ...(input.maxFiles === undefined ? {} : { maxFiles: input.maxFiles }),
    }),
);
const readAttachment = query(
  {
    description:
      "Read up to 64 KiB of a cloud attachment as base64. Continue with offset=next and the same at; null next means complete.",
    input: file,
  },
  (ctx: Read, input) => ctx.drive.attachment(readInput(input)),
);
const operationStatus = query(
  {
    description:
      "Recover a saved, landed or conflicting operation after an unknown reply. Reuse the original operation id.",
    input: object({ operation: string() }),
  },
  (ctx: Read, input) => ctx.drive.receipt(input),
);
const resolveConflict = mutation(
  {
    description:
      "Save reviewed conflict choices with both Git parents. Exact main and writer heads must still match. Null content deletes that path.",
    approval: always(),
    input: object({
      ref: string(),
      expected: string(),
      main: string(),
      edits: array(object({ path: string(), content: jsonSchema({ type: ["string", "null"] }) })),
      operation: string(),
    }),
  },
  (ctx: Write, input) =>
    ctx.drive.resolve({
      ...input,
      edits: input.edits.map((edit) => {
        if (edit.content !== null && typeof edit.content !== "string")
          throw new TypeError("Conflict content must be text or null");
        return { ...edit, content: edit.content };
      }),
    }),
);
const history = query(
  {
    description: "Read retained cloud versions and both parents of merged edits.",
    input: object({ at: string().optional(), limit: number().optional() }),
  },
  (ctx: Read, input) =>
    ctx.drive.history({
      ...(input.at === undefined ? {} : { at: input.at }),
      ...(input.limit === undefined ? {} : { limit: input.limit }),
    }),
);
const createNote = mutation(
  {
    description:
      "Create a cloud note without replacing an existing path. Supply the base from list/read and reuse operation unchanged on retry. Conflicts preserve the saved branch.",
    approval: always(),
    input: write,
  },
  (ctx: Write, input) => ctx.drive.write({ ...input, mode: "create" }),
);
const editNote = mutation(
  {
    description:
      "Edit an existing note from its read base. Git combines clean concurrent edits and preserves conflicts for review.",
    approval: always(),
    input: write,
  },
  (ctx: Write, input) => ctx.drive.write({ ...input, mode: "edit" }),
);
const moveNote = mutation(
  {
    description:
      "Move a cloud note while refusing an existing destination. Its old versions remain in history.",
    approval: always(),
    input: object({ base: string(), from: string(), to: string(), operation: string() }),
  },
  (ctx: Write, input) => ctx.drive.move(input),
);
const deleteNote = mutation(
  {
    description: "Remove a note from the current vault while retaining its history.",
    approval: always(),
    input: object({ base: string(), path: string(), operation: string() }),
  },
  (ctx: Write, input) => ctx.drive.remove(input),
);
const restoreVersion = mutation(
  {
    description:
      "Restore a historical note as a new edit at base. This preserves intervening history.",
    approval: always(),
    input: object({ base: string(), from: string(), path: string(), operation: string() }),
  },
  (ctx: Write, input) => ctx.drive.restore(input),
);
export default defineApp(requirements, {
  tools: router({
    ...changeTools,
    ...importTools,
    ...attachmentTools,
    applyNotes,
    listNotes,
    readNote,
    readAttachment,
    operationStatus,
    resolveConflict,
    searchNotes,
    history,
    createNote,
    editNote,
    moveNote,
    deleteNote,
    restoreVersion,
  }),
});
